@Composable
private fun FeatureEffectHandler(
    effectFlow: Flow<FeatureEffect?>,
    onAction: (FeatureAction) -> Unit,
) {
    val activity = LocalActivity.current ?: return
    LaunchedEffectHandler(
        effectFlow = effectFlow,
        onConsumeEffect = { onAction(FeatureAction.ConsumeEffect) },
        onEffect = { effect ->
            when (effect) {
                is FeatureEffect.ShowToast -> Toast.makeText(activity, effect.messageRes, Toast.LENGTH_SHORT).show()
                is FeatureEffect.OpenDeeplink -> activity.startActivity(Intent(Intent.ACTION_VIEW, effect.url.toUri()))
            }
        }
    )
}
